export const footerHtml = "<footer><div class=\"wrap\">\n  <div class=\"f-top\">\n    <div><a class=\"brand\" href=\"/\"><img class=\"watchtower-footer-mark\" src=\"/watchtower-mark.svg\" width=\"42\" height=\"42\" alt=\"\" /><span>Watchtower</span></a><p class=\"f-b\">Permanently funded compute.</p></div>\n    <div class=\"f-col\"><h4>This submission</h4><ul><li><a href=\"/\">Overview</a></li><li><a href=\"https://github.com/JTraversa/corpus-monad\">Source</a></li></ul></div>\n    <div class=\"f-col\"><h4>corpusAI Cloud Pricing</h4><ul><li><a href=\"https://cloud.trycorpus.ai/charts\">Charts</a></li><li><a href=\"https://cloud.trycorpus.ai/docs\">API</a></li><li><a href=\"https://cloud.trycorpus.ai/x402\">Pay per request (x402)</a></li></ul></div>\n    <div class=\"f-col\"><h4>Contact</h4><ul><li><a href=\"mailto:hello@trycorpus.ai\">hello@trycorpus.ai</a></li><li><a href=\"https://www.trycorpus.ai/terms\">Terms</a></li><li><a href=\"https://www.trycorpus.ai/privacy\">Privacy</a></li></ul></div>\n  </div>\n  <div class=\"f-bottom\"><p class=\"legal\">© 2026 Watchtower. A hackathon proof of concept on Fly-sized machines; the yearly rate positions are priced at is not a quote or a guarantee. Nothing on this page is an offer to sell a security or a commodity contract.</p></div>\n</div></footer>";
export const computeToolsMarkup = "<section id=\"me-root\" class=\"wrap compute-tools\" aria-label=\"Compute payment and verification tools\">\n    \n    <div class=\"sec-head\"><p class=\"eyebrow\">Compute payment & verification</p><h2>Settle jobs. Verify prices.</h2><p class=\"lead\">Additional payment options for corpus compute on the network selected above. Machine ownership and redemption remain in the catalogue.</p></div>\n    <div class=\"strip-card\"><div class=\"strip-bar\"><span id=\"me-network\">RPC not connected</span><span id=\"me-wallet\">Wallet disconnected</span><button id=\"me-connect\" class=\"btn sm\">Connect for job payments</button></div></div>\n    <div class=\"notice\" id=\"me-setup\">Loading configuration…</div>\n<section class=\"stats\"><div><span>NETWORK</span><strong id=\"me-chain\">—</strong></div><div><span>PROVIDER OFFERS</span><strong id=\"me-offers-count\">—</strong></div><div><span>MEC IN ESCROW</span><strong id=\"me-escrow\">—</strong></div><div><span>YOUR WITHDRAWABLE MEC</span><strong id=\"me-credit\">—</strong><button id=\"me-withdraw\" class=\"text-button\">Withdraw ↗</button></div></section>\n<section id=\"me-market\"><div class=\"section-title\"><div><div class=\"eyebrow\">01 / BUYER-CONTROLLED SETTLEMENT</div><h2>A clear deal, on-chain.</h2></div><button id=\"me-refresh\" class=\"secondary\">Refresh data ↻</button></div>\n<p class=\"muted\">Funds stay in escrow until you accept delivery. After the deadline, unaccepted orders can be refunded. A configured demo worker can run one fixed GPU reference task; it does not accept arbitrary code.</p>\n<div class=\"grid\"><article class=\"card\"><h3>Place an order</h3><label for=\"me-offer-id\">Offer ID</label><input id=\"me-offer-id\" type=\"number\" min=\"1\" step=\"1\" value=\"1\"><button id=\"me-load-offer\" class=\"text-button\">Inspect offer ↗</button><pre id=\"me-offer-detail\">Inspect an offer to see its provider, specification hash and MEC price.</pre><label for=\"me-units\">Compute units</label><input id=\"me-units\" type=\"number\" min=\"1\" max=\"10000\" step=\"1\" value=\"1\"><label for=\"me-request\">Your request / agreed specification</label><textarea id=\"me-request\" placeholder=\"Describe the agreed workload. Keep a copy off-chain; only its hash is stored.\"></textarea><p class=\"muted small\" id=\"me-order-total\">Price is read from the contract before payment.</p><button id=\"me-order\" class=\"primary\">Pay into escrow ↗</button><div class=\"provider-job-panel\"><div class=\"provider-job-heading\"><strong>Single-provider GPU demo</strong><span id=\"me-provider-health\" class=\"tag\">Checking relay…</span></div><p class=\"muted small\">Confirmed orders can be queued to the reference GPU worker. The provider still signs delivery from their own wallet.</p><label for=\"me-job-id\">Provider job ID</label><div class=\"provider-job-controls\"><input id=\"me-job-id\" placeholder=\"Filled after ordering; share with provider\" autocomplete=\"off\"><button id=\"me-load-job\" class=\"secondary\">Load job</button></div><p id=\"me-job-status\" class=\"muted small\" role=\"status\" aria-live=\"polite\">No remote job loaded.</p><pre id=\"me-job-result\">Place an order to queue the fixed GPU reference task.</pre><button id=\"me-use-job-receipt\" class=\"secondary\">Load GPU receipt into delivery form</button></div></article>\n<article class=\"card\"><h3>Publish a compute offer</h3><p class=\"muted small\">Anyone can be a provider. Agree on the work and receipt format with your buyer before accepting an order.</p><label for=\"me-spec\">Specification (hashed on-chain)</label><textarea id=\"me-spec\" placeholder=\"Example: one benchmark run, input limit, expected output and delivery terms\"></textarea><div class=\"two\"><div><label for=\"me-price\">MEC per unit</label><input id=\"me-price\" value=\"0.01\" inputmode=\"decimal\"></div><div><label for=\"me-duration\">Delivery window (seconds)</label><input id=\"me-duration\" type=\"number\" min=\"60\" max=\"2592000\" step=\"1\" value=\"3600\"></div></div><button id=\"me-publish\" class=\"secondary\">Publish offer ↗</button><p class=\"muted small\">Price is set by the provider in MEC. The USD price oracle is a separate reference; it is not a MEC exchange rate.</p><label for=\"me-toggle-offer-id\">Your offer ID</label><input id=\"me-toggle-offer-id\" type=\"number\" min=\"1\" step=\"1\" value=\"1\"><div class=\"two\"><button id=\"me-pause-offer\" class=\"secondary\">Pause offer</button><button id=\"me-resume-offer\" class=\"secondary\">Resume offer</button></div></article></div>\n<article class=\"card orders\"><div class=\"section-title\"><h3>Orders & delivery</h3><span class=\"tag\">LATEST 25 ORDERS</span></div><div class=\"table-scroll\"><table><thead><tr><th>Order</th><th>Buyer / provider</th><th>Units · MEC</th><th>State</th><th>Deadline</th></tr></thead><tbody id=\"me-orders\"><tr><td colspan=\"5\">Configure the market contract to read orders.</td></tr></tbody></table></div><div class=\"two\"><div><label for=\"me-order-id\">Order ID</label><input id=\"me-order-id\" type=\"number\" min=\"1\" step=\"1\" value=\"1\"></div><div><label for=\"me-receipt\">Original delivery receipt (provider or buyer)</label><textarea id=\"me-receipt\" rows=\"8\" class=\"code\" placeholder=\"Run the CPU reference workload, or paste the agreed receipt from your provider\"></textarea></div></div><button id=\"me-generate-reference\" class=\"secondary\">Run local CPU reference job</button><p id=\"me-reference-result\" class=\"muted small\">Optional reference workload: 4,096 sequential SHA-256 rounds in this browser. It does not call a GPU or remote provider.</p><div class=\"actions\"><button id=\"me-inspect-order\" class=\"secondary\">Inspect order</button><button id=\"me-check-receipt\" class=\"secondary\">Check receipt & result</button><button id=\"me-deliver\" class=\"secondary\">Record delivery</button><button id=\"me-accept\" class=\"primary\">Accept & release payment</button><button id=\"me-refund\" class=\"secondary\">Refund expired order</button></div><pre id=\"me-order-detail\">Inspect an order to see the original request and receipt hashes.</pre><p class=\"muted small\">Before acceptance, verify that the receipt is bound to the on-chain request. Delivery stores a receipt hash, not the output. Buyer and provider exchange the receipt off-chain. A receipt is a provider claim, not cryptographic proof that a GPU ran. Buyers may refund an unaccepted order at expiry, including a delivered order.</p></article>\n</section>\n<section id=\"me-oracle\"><div class=\"section-title\"><div><div class=\"eyebrow\">02 / VERIFIABLE PRICE RECORDS</div><h2>A price you can check.</h2></div><span class=\"tag\">EIP-712 SIGNATURES</span></div><div class=\"grid\"><article class=\"card\"><h3>Verify & relay a fixing</h3><p class=\"muted small\">Paste a signed corpusAI fixing. The publisher signature is checked before relay. A historical record is never presented as a live quote.</p><label for=\"me-fixing\">Signed fixing JSON</label><textarea id=\"me-fixing\" class=\"code\" rows=\"8\"></textarea><div class=\"actions\"><button id=\"me-sample\" class=\"secondary\">Load historical example</button><button id=\"me-verify\" class=\"secondary\">Verify signature</button><button id=\"me-relay\" class=\"primary\">Relay to ME ↗</button></div><p id=\"me-verify-result\" class=\"muted small\" aria-live=\"polite\">No fixing verified yet.</p></article><article class=\"card\"><h3>Read the on-chain record</h3><label for=\"me-ticker\">Compute index ticker</label><input id=\"me-ticker\" value=\"CX.H100SXM.NEO\"><button id=\"me-read-price\" class=\"secondary\">Read oracle ↗</button><pre id=\"me-price-record\">No record loaded.</pre><p class=\"muted small\">This feed is an independent, pre-existing corpusAI service. The app can relay any valid signed fixing supplied as JSON; obtaining fresh paid data is optional.</p></article></div></section>\n<section id=\"me-identity\"><div class=\"section-title\"><div><div class=\"eyebrow\">03 / META EARTH IDENTITY</div><h2>Look up an ME identity.</h2></div></div><article class=\"card\"><p class=\"muted\">Query the official ME Hub REST API for an ETH-derived ME sub-account. Public identity data helps counterparties inspect a provider; it does not prove control of an entered address or gate escrow.</p><label for=\"me-me-address\">ME sub-account address</label><input id=\"me-me-address\" placeholder=\"me1…\" autocomplete=\"off\"><button id=\"me-lookup\" class=\"secondary\">Query ME ID ↗</button><pre id=\"me-identity-result\">Configure VITE_ME_REST to enable this optional lookup.</pre></article></section>\n<section id=\"me-evidence\"><div class=\"section-title\"><div><div class=\"eyebrow\">04 / REPRODUCIBLE EVIDENCE</div><h2>Show the work.</h2></div><button id=\"me-export\" class=\"secondary\">Export session evidence ↓</button></div><p class=\"muted\">Network, contract addresses, and confirmed transaction hashes. Local chain evidence is labeled as local development.</p><pre id=\"me-activity\" role=\"status\" aria-live=\"polite\">Ready. Transactions require your wallet signature.</pre></section>\n\n  </section>";
